package com.bitedash.repository; import com.bitedash.entity.Restaurant; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface RestaurantRepository extends JpaRepository<Restaurant,Long>{@Query("select r from Restaurant r where r.active=true and (:search is null or lower(r.name) like lower(concat('%',:search,'%')) or lower(r.cuisine) like lower(concat('%',:search,'%'))) and (:category is null or lower(r.cuisine) like lower(concat('%',:category,'%'))) order by r.name") List<Restaurant> search(@Param("search") String search,@Param("category") String category);}
